window.KHO_DATA_L1_TIENGANH = [
{"lop":1,"mon":"Tiếng Anh","tuan":1,"tiet":1,"bai":"Unit 1: In the school playground – Lesson 1 (1, 2) & Lesson 2 (3, 4, 5)","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter B b and say its sound /b/ correctly.\n- Listen, point and say the words Bill, ball, bike and book correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter B b.\n2. Skills: Listening and speaking\n3. Attributes:\n- Greet teachers and friends politely.\n- Be friendly, take turns and help friends in pairs and groups.\n4. Digital Competence (1.3CB1a): Access and open the lesson audio files on the safe digital learning website hoclieu.vn with the teacher’s guidance.","dodung":"- Teacher: Teacher’s guide pages 7, 8, 9, audio Track 2, website hoclieu.vn, flashcards/pictures (Unit 1), poster (Unit 1), computer, projector, the website hoclieu.vn opened on the class computer, lesson plan.\n- Pupils: Pupil’s Book page 6, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To greet the class, get to know each other and start the English 1 book.\n* Procedure:\n- T greets the class with a big wave: “Hello, class! I’m (T’s name).”\n- T sings a short “Hello” song with actions; Ss join in.\n- T shows the Pupil’s Book and the pictures of the characters.\n- T says: “Open your books at page 6.” and shows Unit 1: In the school playground.","hs":"- Ss wave and say: “Hello, teacher!”\n- Ss listen, sing and do the actions.\n- Ss look at the book.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /b/ of the letter B b and the words Bill, ball, bike and book.\n* Procedure:\n- T shows the letter card B b and says the sound /b/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ Bill: bạn Bill (picture)\n+ ball: quả bóng (realia)\n+ bike: xe đạp (picture)\n+ book: quyển sách (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /b/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /b/ and the words.\n* Procedure:\n- (Digital competence 1.3CB1a) Before the chant, T shows on the projector how to open the safe learning website hoclieu.vn, find English 1 – Unit 1 and click the audio icon; T invites 2 Ss to click “Play” to open the chant audio.\n- T reminds Ss: open learning websites only with the teacher or with parents.\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- 2 Ss click the audio icon on the class computer with T’s help; the class watches the steps.\n- Ss listen and repeat the rule.\n- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter B b correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter B b on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter B b, the sound /b/ and the words Bill, ball, bike and book again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":2,"tiet":1,"bai":"Unit 1: In the school playground – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “Hi, I’m Bill.” – “Bye, Bill.” to greet a friend, say their own name and say goodbye.\n- Say their own names in the pattern and say goodbye to friends.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Greet teachers and friends politely.\n- Listen to the teacher and friends politely.\n4. Digital Competence (1.1CB1a): Listen to the lesson audio on the class computer and point to the right character on the screen to find the information they hear.","dodung":"- Teacher: Teacher’s guide pages 11–13, audio Tracks 5, 6, website hoclieu.vn, flashcards/pictures (Unit 1), poster (Unit 1), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 8, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (Bill, ball, bike and book); Ss say the words.\n- T says: “Open your books at page 8.” and shows Unit 1: In the school playground, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “Hi, I’m Bill.” – “Bye, Bill.”.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the picture on the projector and plays the audio on the class computer; Ss point to Bill or Linh on the screen when they hear the name.\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  Hi, I’m Bill.\n  Bye, Bill.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss listen and point to the right character on the screen.\n- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “Hi, I’m Bill.” – “Bye, Bill.” in a short talk.\n* Procedure:\n- T models with a S: T: “Hi, I’m (T’s name).” – S: “Hi, I’m Linh.” – T: “Bye, Linh.”\n- Ss stand up, walk around, greet 3 friends with their own names and say goodbye.\n- T praises Ss and corrects pronunciation.","hs":"- Ss listen and watch the model.\n- Ss greet friends: “Hi, I’m …” – “Bye, …”.\n- Ss listen."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the “Hello” song about Ba and Bill saying hello and their names with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: wave their hands for “Hi” and “Bye”.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “Hi, I’m Bill.” – “Bye, Bill.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":3,"tiet":1,"bai":"Unit 2: In the dining room – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter C c and say its sound /k/ correctly.\n- Listen, point and say the words cake, car, cat and cup correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter C c.\n2. Skills: Listening and speaking\n3. Attributes:\n- Share toys and food with family and friends.\n- Listen to the teacher and friends politely.\n4. Digital Competence (1.1CB1a): Look at the pictures on the projector and listen to the audio on the class computer to find the right word (cake, car, cat, cup).","dodung":"- Teacher: Teacher’s guide pages 14–18, audio Tracks 7, 8, 9, website hoclieu.vn, flashcards/pictures (Unit 2), poster (Unit 2), computer, projector, lesson plan.\n- Pupils: Pupil’s Book pages 9, 10, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 1.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Pass the ball”: T plays music; Ss pass a ball around the class.\n- When the music stops, the S with the ball says a word from Unit 1 (Bill, ball, bike and book).\n- T says: “Open your books at pages 9, 10.” and shows Unit 2: In the dining room.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss pass the ball.\n- Ss say a word when the music stops.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /k/ of the letter C c and the words cake, car, cat and cup.\n* Procedure:\n- T shows the letter card C c and says the sound /k/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ cake: bánh ngọt (picture)\n+ car: xe ô tô (realia)\n+ cat: con mèo (picture)\n+ cup: cái cốc (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T shows the four pictures on the projector one by one, plays the word audio and asks Ss to come up and point to the right picture on the screen.","hs":"- Ss look and listen.\n- Ss say the sound /k/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen, come up and point to the right picture on the screen."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /k/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter C c correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter C c on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter C c, the sound /k/ and the words cake, car, cat and cup again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":4,"tiet":1,"bai":"Unit 2: In the dining room – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “I have a car.” to say what they have.\n- Say the words cake, car, cat and cup in the sentence pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Share toys and food with family and friends.\n- Love learning English and be confident when speaking.\n4. Digital Competence (3.1CB1a): Practise drawing a simple birthday cake in Paint on the class computer.","dodung":"- Teacher: audio, flashcards/pictures (Unit 2), poster (Unit 2), computer, projector, Paint on the class computer, lesson plan.\n- Pupils: Pupil’s Book, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (cake, car, cat and cup); Ss say the words.\n- T says: “Open your books, please.” and shows Unit 2: In the dining room, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “I have a car.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  I have a car.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (9’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “I have a car.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “I have a car.”\n- Ss say the sentence for each picture:\n  Picture a – I have a car.\n  Picture b – I have a cake.\n  Picture c – I have a cup.\n  Picture d – I have a cat.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (12’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the song “I have …” with cup, car, cake and cat with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: hold up a toy or a picture when they sing “I have …”.\n- Groups take turns to sing; then the whole class sings together.\n- (Digital competence 3.1CB1a) T opens Paint on the class computer and shows the tools: shapes (circle, rectangle), the brush and the colours.\n- T draws a simple birthday cake (a rectangle and three candles) as a model.\n- 3–4 Ss take turns to draw a simple cake with T’s help and say: “I have a cake.”","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class.\n- Ss look at the tools on the screen.\n- Ss watch T draw.\n- 3–4 Ss draw a cake in Paint and say: “I have a cake.”; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “I have a car.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":5,"tiet":1,"bai":"Fun time 1","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters B b and C c and their sounds /b/, /k/.\n- Say the words of Units 1 and 2: Bill, ball, bike, book, cake, car, cat and cup.\n- Use the patterns “Hi, I’m …” and “I have a …” in games.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be friendly, take turns and help friends in pairs and groups.\n- Play fairly and cheer for their friends.\n4. Digital Competence (1.1CB1a): Look at the word pictures of Units 1 and 2 on the projector and find the right picture when they hear a word.","dodung":"- Teacher: Teacher’s guide pages 20, 21, 22, audio, website hoclieu.vn, flashcards/pictures (Units 1 and 2), word cards, computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 12, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a happy atmosphere and revise the units.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss sing the song “I have …” from Unit 2 with actions.\n- T says: “Open your books at page 12.” and shows Fun time 1.","hs":"- Ss greet T.\n- Ss sing and do the actions.\n- Ss open their books."},{"ten":"2. Revision (8’)","gv":"Revision of letters and words.\n* Aims: Ss can say the letters B b, C c and the words of Units 1 and 2.\n* Procedure:\n- T shows the letter cards B b and C c; Ss say the letters and the sounds.\n- T shows the flashcards; Ss say the words:\n+ Bill: bạn Bill (picture)\n+ ball: quả bóng (realia)\n+ bike: xe đạp (picture)\n+ book: quyển sách (realia)\n+ cake: bánh ngọt (picture)\n+ car: xe ô tô (realia)\n+ cat: con mèo (picture)\n+ cup: cái cốc (realia)\n- Game “What’s missing?” with the flashcards.","hs":"- Ss say the letters and the sounds.\n- Ss say the words: chorus, groups, individuals.\n- Ss play the game."},{"ten":"3. Practice (10’)","gv":"Activity 1. Find and circle. Then say.\n* Aims: Ss can find the things in the picture and say the words.\n* Procedure:\n- T models: find the ball in the big picture, circle it with a pencil and say: “ball”.\n- Ss find and circle six things: bike, cup, book, cat, car, ball.\n- Ss say the words in pairs; T checks with the class.","hs":"- Ss look and listen.\n- Ss find, point and say.\n- Ss check the answers."},{"ten":"4. Production (11’)","gv":"Activity 2. Let’s play: “Simon says” with letters.\n* Aims: Ss can use the words and patterns in a fun activity.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the pictures of Units 1 and 2 on the projector (hoclieu.vn); T says a word, Ss come up and point to the right picture on the screen.\n- T says: “Simon says: make a big B!” / “Simon says: make a small c!”; Ss use their arms and bodies to make the letters B b and C c.\n- Ss who move without “Simon says” sit down for one turn.\n- (If time is short, T shortens the game.)","hs":"- Ss listen, come up and point to the right picture on the screen.\n- Ss make the letters with their bodies.\n- Ss listen carefully and play.\n- Ss have fun and say the letters."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which words of Units 1 and 2 they like best.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the words to your family.","hs":"- Ss say their favourite words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":6,"tiet":1,"bai":"Unit 3: At the street market – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter A a and say its sound /æ/ correctly.\n- Listen, point and say the words apple, bag, can and hat correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter A a.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep their own things carefully.\n- Love learning English and be confident when speaking.\n4. Digital Competence (1.1CB1b): Search safely for pictures of a country market with the teacher on the class computer.","dodung":"- Teacher: Teacher’s guide pages 24, 25, 26, audio, website hoclieu.vn, flashcards/pictures (Unit 3), poster (Unit 3), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 14, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 2.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Lucky box”: T puts the pictures of Unit 2 (cake, car, cat and cup) in a box.\n- Ss take turns to pick a picture and say the word; the class claps.\n- T says: “Open your books at page 14.” and shows Unit 3: At the street market.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss watch.\n- Ss pick a picture and say the word.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /æ/ of the letter A a and the words apple, bag, can and hat.\n* Procedure:\n- T shows the letter card A a and says the sound /æ/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ apple: quả táo (realia)\n+ bag: cái túi (realia)\n+ can: cái lon (realia)\n+ hat: cái mũ (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /æ/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /æ/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter A a correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter A a on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 1.1CB1b) T turns on safe search on the class computer and types “country market” while Ss watch; T chooses a safe picture and shows it on the projector.\n- T asks: “What can you see?”; Ss find and name apples, bags, hats and cans in the picture.\n- T reminds Ss: search the Internet only with a teacher or with parents.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss watch T search safely.\n- Ss point and say: “apple”, “bag”, “hat”, “can”.\n- Ss listen and repeat the rule."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter A a, the sound /æ/ and the words apple, bag, can and hat again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":7,"tiet":1,"bai":"Unit 3: At the street market – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “This is my bag.” to show and name their own things.\n- Say the words apple, bag, can and hat in the sentence pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep their own things carefully.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (AI 1.C1.3): Know simply how an AI camera scans pictures and recognises circles and squares in real life.","dodung":"- Teacher: Teacher’s guide pages 28, 29, audio, website hoclieu.vn, flashcards/pictures (Unit 3), poster (Unit 3), computer, projector, pictures of round and square things at the market, lesson plan.\n- Pupils: Pupil’s Book page 16, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (apple, bag, can and hat); Ss say the words.\n- T says: “Open your books at page 16.” and shows Unit 3: At the street market, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “This is my bag.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  This is my bag.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (9’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “This is my bag.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “This is my bag.”\n- Ss say the sentence for each picture:\n  Picture a – This is my bag.\n  Picture b – This is my hat.\n  Picture c – This is my apple.\n  Picture d – This is my can.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (12’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song with apple, hat, bag and can with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: hold up their own bag or hat when they sing.\n- Groups take turns to sing; then the whole class sings together.\n- (AI 1.C1.3) T shows a market picture on the projector and explains simply: “An AI camera looks at a picture. It can find circles and squares.”\n- T shows the same picture with circles around the round things (apples) and squares around the square things (bags).\n- Game “I am an AI camera”: T shows a real thing or a picture; Ss draw a circle or a square in the air, say “Circle!” or “Square!”, then say “This is my apple.” / “This is my bag.”","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class.\n- Ss look and listen.\n- Ss point to the circles and the squares.\n- Ss play the game and say the sentences."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “This is my bag.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":8,"tiet":1,"bai":"Unit 4: In the bedroom – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter D d and say its sound /d/ correctly.\n- Listen, point and say the words desk, dog, door and duck correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter D d.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep their bedroom clean and tidy.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.1CB1a): Listen to the audio on the class computer and point to the right pictures in the Pupil’s Book (desk, dog, door, duck).","dodung":"- Teacher: Teacher’s guide pages 30, 31, 32, audio Track 17, website hoclieu.vn, flashcards/pictures (Unit 4), poster (Unit 4), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 17, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 3.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Jump and say”: T puts the flashcards of Unit 3 (apple, bag, can and hat) on the floor.\n- T says a word; a S jumps onto the right card and says the word.\n- T says: “Open your books at page 17.” and shows Unit 4: In the bedroom.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss jump and say the words.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /d/ of the letter D d and the words desk, dog, door and duck.\n* Procedure:\n- T shows the letter card D d and says the sound /d/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ desk: cái bàn học (picture)\n+ dog: con chó (picture)\n+ door: cái cửa ra vào (picture)\n+ duck: con vịt (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T plays the word audio on the class computer in a new order; Ss listen and point to the right picture in their books.","hs":"- Ss look and listen.\n- Ss say the sound /d/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen and point to the right picture in their books."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /d/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter D d correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter D d on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter D d, the sound /d/ and the words desk, dog, door and duck again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":9,"tiet":1,"bai":"Unit 4: In the bedroom – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “This is a dog.” to name things and animals in a picture.\n- Say the words desk, dog, door and duck in the sentence pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep their bedroom clean and tidy.\n- Be friendly, take turns and help friends in pairs and groups.\n4. Digital Competence (1.1CB1a): Watch and listen to the song on hoclieu.vn on the projector and follow the words and the actions.","dodung":"- Teacher: Teacher’s guide pages 34, 35, 36, audio Tracks 20, 21, website hoclieu.vn, flashcards/pictures (Unit 4), lesson plan.\n- Pupils: Pupil’s Book page 19, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (desk, dog, door and duck); Ss say the words.\n- T says: “Open your books at page 19.” and shows Unit 4: In the bedroom, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “This is a dog.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  This is a dog.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “This is a dog.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “This is a dog.”\n- Ss say the sentence for each picture:\n  Picture a – This is a dog.\n  Picture b – This is a duck.\n  Picture c – This is a door.\n  Picture d – This is a desk.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about a dog and a duck in the bedroom with actions.\n* Procedure:\n- (Digital competence 1.1CB1a) T opens the song on hoclieu.vn on the projector; Ss watch, listen and point to the dog, the duck, the door and the desk.\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: point to the pictures and act like a dog and a duck.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss watch the screen, listen and point.\n- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “This is a dog.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":10,"tiet":1,"bai":"Unit 5: At the fish and chip shop – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter I i and say its sound /ɪ/ correctly.\n- Listen, point and say the words chicken, chips, fish and milk correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter I i.\n2. Skills: Listening and speaking\n3. Attributes:\n- Eat healthy food and do not waste food.\n- Be friendly, take turns and help friends in pairs and groups.\n- Ethics: Say “Thank you” when receiving food from parents or shop staff.\n4. Digital Competence (AI 1.C1.1): Recognise the AI system in automatic ordering machines that quickly identifies fish dishes.","dodung":"- Teacher: Teacher’s guide pages 42–44, audio Track 26, website hoclieu.vn, computer, projector, a picture of a self-ordering machine at a food shop, lesson plan.\n- Pupils: Pupil’s Book page 23, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 4.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T sticks the flashcards of Unit 4 on the board (desk, dog, door and duck).\n- Game “Slap the board”: T says a word; one S from each team runs and slaps the right card.\n- T says: “Open your books at page 23.” and shows Unit 5: At the fish and chip shop.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss play in two teams and say the words aloud.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /ɪ/ of the letter I i and the words chicken, chips, fish and milk.\n* Procedure:\n- T shows the letter card I i and says the sound /ɪ/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ chicken: thịt gà (picture)\n+ chips: khoai tây chiên (picture)\n+ fish: cá (picture)\n+ milk: sữa (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /ɪ/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /ɪ/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter I i correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter I i on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (AI 1.C1.1) T shows a picture of a self-ordering machine at a food shop and says: “This machine has AI. It looks at the picture and knows: fish!”\n- Game “Ordering machine”: one S is the machine, another S points to a food picture (fish, chips, chicken, milk); the “machine” quickly says the word and gives the picture; the customer says: “Thank you.”\n- T reminds Ss: say “Thank you” when parents or shop staff give you food.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss look and listen.\n- Ss play in pairs and say “Thank you.”\n- Ss repeat: “Thank you.”"},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter I i, the sound /ɪ/ and the words chicken, chips, fish and milk again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":11,"tiet":1,"bai":"Unit 5: At the fish and chip shop – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “I like milk.” to say what food and drinks they like.\n- Say the words chicken, chips, fish and milk in the sentence pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Eat healthy food and do not waste food.\n- Listen to the teacher and friends politely.\n4. Digital Competence (AI 1.D1.1): Know that to teach a robot the types of milk, people must show it the right pictures (strawberry milk and plain milk cartons) so that it does not learn wrongly.","dodung":"- Teacher: Teacher’s guide pages 46, 47, audio Tracks 29, 30, website hoclieu.vn, flashcards/pictures (Unit 5), poster (Unit 5), computer, projector, pictures of a strawberry milk carton, a plain milk carton and a juice box, lesson plan.\n- Pupils: Pupil’s Book page 25, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (chicken, chips, fish and milk); Ss say the words.\n- T says: “Open your books at page 25.” and shows Unit 5: At the fish and chip shop, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “I like milk.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  I like milk.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (9’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “I like milk.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “I like milk.”\n- Ss say the sentence for each picture:\n  Picture a – I like milk.\n  Picture b – I like chips.\n  Picture c – I like fish.\n  Picture d – I like chicken.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (12’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about fish and chips, milk and chicken with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: rub their tummies and say “Yummy!”.\n- Groups take turns to sing; then the whole class sings together.\n- (AI 1.D1.1) T holds up a “robot” card and says: “I am a robot. I want to learn: milk.”\n- Ss show the robot the right pictures, a strawberry milk carton and a plain milk carton, and say: “Milk!”\n- T shows a wrong picture (a juice box) and asks: “Milk?”; Ss say: “No!” T explains simply: if we show the robot wrong pictures, it learns wrongly.\n- Ss finish with: “I like milk.”","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class.\n- Ss look and listen.\n- Ss hold up the milk pictures and say: “Milk!”\n- Ss say: “No!”\n- Ss say: “I like milk.”"},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “I like milk.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":12,"tiet":1,"bai":"Unit 6: In the classroom – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter E e and say its sound /e/ correctly.\n- Listen, point and say the words bell, pen, pencil and red correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter E e.\n2. Skills: Listening and speaking\n3. Attributes:\n- Look after their school things.\n- Listen to the teacher and friends politely.\n4. Digital Competence (AI 1.C1.1; 4.1CB1a): Recognise AI in the smart interactive board that helps the teacher practise writing the letters and the words pen, pencil; turn off the computer at the end of the lesson to protect the device.","dodung":"- Teacher: Teacher’s guide pages 48, 49, 50, audio Track 31, website hoclieu.vn, flashcards/pictures (Unit 6), poster (Unit 6), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 26, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 5.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T shows the flashcards of Unit 5 one by one (chicken, chips, fish and milk); Ss say the words.\n- Game “What’s missing?”: T hides one card; Ss say the missing word.\n- T says: “Open your books at page 26.” and shows Unit 6: In the classroom.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the words.\n- Ss guess the missing card.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /e/ of the letter E e and the words bell, pen, pencil and red.\n* Procedure:\n- T shows the letter card E e and says the sound /e/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ bell: cái chuông (realia)\n+ pen: cái bút mực (realia)\n+ pencil: cái bút chì (realia)\n+ red: màu đỏ (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /e/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /e/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (7’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter E e correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter E e on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (AI 1.C1.1) T writes “pen” and “pencil” on the smart interactive board; the board changes the handwriting into neat letters. T says: “The smart board has AI. It helps me write.” (If there is no smart board, T shows pictures of one.)","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss watch the board and say: “pen”, “pencil”."},{"ten":"5. Wrap-up (3’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter E e, the sound /e/ and the words bell, pen, pencil and red again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.\n- (Digital competence 4.1CB1a) T shows how to turn off the computer: close the programs, click Start – Power – Shut down; one S clicks with T’s help.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task.\n- One S turns off the computer with T; the class says: “Bye, computer!”"}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":13,"tiet":1,"bai":"Unit 6: In the classroom – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “It’s a red pencil.” to say the colour of a school thing.\n- Say the words pen, pencil, desk and bell with the colour red.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Look after their school things.\n- Love learning English and be confident when speaking.\n4. Digital Competence (AI 1.A1.1; 3.1CB1a): Understand simply that people decide to use pencils to draw creative pictures and AI only follows commands; practise drawing a classroom object (a rectangle) on the computer.","dodung":"- Teacher: Teacher’s guide pages 52, 53, audio Tracks 34, 35, website hoclieu.vn, flashcards/pictures (Unit 6), poster (Unit 6), computer, projector, Paint on the class computer, lesson plan.\n- Pupils: Pupil’s Book page 28, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (bell, pen, pencil and red); Ss say the words.\n- T says: “Open your books at page 28.” and shows Unit 6: In the classroom, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “It’s a red pencil.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  It’s a red pencil.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (9’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “It’s a red pencil.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “It’s a red pencil.”\n- Ss say the sentence for each picture:\n  Picture a – It’s a red pencil.\n  Picture b – It’s a red pen.\n  Picture c – It’s a red desk.\n  Picture d – It’s a red bell.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (12’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about Jen’s red pen and Ben’s red pencil with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: hold up a red pen or a red pencil.\n- Groups take turns to sing; then the whole class sings together.\n- (AI 1.A1.1) T holds up a red pencil and asks: “Who draws a picture? You or the computer?” T explains with gestures: “You choose. You draw. AI only follows commands.”\n- (Digital competence 3.1CB1a) T opens Paint and shows the rectangle tool and the red colour; 3 Ss take turns to draw a red rectangle (a desk) and say: “It’s a red desk.”","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class.\n- Ss answer: “Me!” and repeat: “AI only follows commands.”\n- 3 Ss draw a red rectangle in Paint and say: “It’s a red desk.”"},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “It’s a red pencil.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":14,"tiet":1,"bai":"Fun time 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters I i and E e and their sounds /ɪ/, /e/.\n- Say the words of Units 5 and 6: chicken, chips, fish, milk, bell, pen, pencil and red.\n- Use the patterns “I like …” and “It’s a red …” in games.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be friendly, take turns and help friends in pairs and groups.\n- Play fairly and cheer for their friends.\n4. Digital Competence (AI 1.C1.1): Compare how fast pupils find words with how fast AI scans data to find the answer in an instant.","dodung":"- Teacher: Teacher’s guide pages 54, 55, audio, website hoclieu.vn, flashcards/pictures (Units 5 and 6), word cards, computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 29, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a happy atmosphere and revise the units.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss sing the unit song from Unit 6 with actions.\n- T says: “Open your books at page 29.” and shows Fun time 2.","hs":"- Ss greet T.\n- Ss sing and do the actions.\n- Ss open their books."},{"ten":"2. Revision (8’)","gv":"Revision of letters and words.\n* Aims: Ss can say the letters I i, E e and the words of Units 5 and 6.\n* Procedure:\n- T shows the letter cards I i and E e; Ss say the letters and the sounds.\n- T shows the flashcards; Ss say the words:\n+ chicken: thịt gà (picture)\n+ chips: khoai tây chiên (picture)\n+ fish: cá (picture)\n+ milk: sữa (realia)\n+ bell: cái chuông (realia)\n+ pen: cái bút mực (realia)\n+ pencil: cái bút chì (realia)\n+ red: màu đỏ (realia)\n- Game “What’s missing?” with the flashcards.","hs":"- Ss say the letters and the sounds.\n- Ss say the words: chorus, groups, individuals.\n- Ss play the game."},{"ten":"3. Practice (10’)","gv":"Activity 1. Look, find and say.\n* Aims: Ss can find the things in the picture and say the words.\n* Procedure:\n- T puts Ss in teams of four and gives each team the picture page.\n- Race: T says a word (chips, fish, milk, chicken, bell, pen, pencil); teams find it, point and say it. T counts the seconds.\n- T checks with the class.\n- (AI 1.C1.1) After the race, T types “pen” into the search box of a word list on the class computer; the computer finds it at once. T says: “Computers and AI look at data very fast. You think and understand. Well done!”","hs":"- Ss look and listen.\n- Ss find, point and say.\n- Ss check the answers.\n- Ss watch the computer find the word and compare it with their race."},{"ten":"4. Production (11’)","gv":"Activity 2. Let’s play: “Bingo” with pictures.\n* Aims: Ss can use the words and patterns in a fun activity.\n* Procedure:\n- T gives each S a card with 4 pictures from Units 5 and 6.\n- T says the words one by one; Ss cover the picture they hear and shout “Bingo!” when all 4 are covered.\n- The winner says: “I like … / It’s a red …” with his or her pictures.","hs":"- Ss take their cards.\n- Ss listen and cover the pictures.\n- Winners say the sentences."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which words of Units 5 and 6 they like best.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the words to your family.","hs":"- Ss say their favourite words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":15,"tiet":1,"bai":"Unit 7: In the garden – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter G g and say its sound /g/ correctly.\n- Listen, point and say the words garden, gate, girl and goat correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter G g.\n2. Skills: Listening and speaking\n3. Attributes:\n- Love nature and look after plants.\n- Love learning English and be confident when speaking.\n- Ethics: Love nature and protect green trees.\n4. Digital Competence (AI 1.C1.1): Recognise smart (AI) devices that automatically water the garden when the soil is dry.","dodung":"- Teacher: Teacher’s guide pages 57, 58, 59, audio, website hoclieu.vn, flashcards/pictures (Unit 7), poster (Unit 7), computer, projector, a picture of a smart watering machine in a garden, lesson plan.\n- Pupils: Pupil’s Book page 31, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 6.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Pass the ball”: T plays music; Ss pass a ball around the class.\n- When the music stops, the S with the ball says a word from Unit 6 (bell, pen, pencil and red).\n- T says: “Open your books at page 31.” and shows Unit 7: In the garden.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss pass the ball.\n- Ss say a word when the music stops.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /g/ of the letter G g and the words garden, gate, girl and goat.\n* Procedure:\n- T shows the letter card G g and says the sound /g/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ garden: khu vườn (picture)\n+ gate: cái cổng (picture)\n+ girl: bạn gái (picture)\n+ goat: con dê (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /g/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /g/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter G g correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter G g on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (AI 1.C1.1) T shows a picture of a smart watering machine in a garden and says: “The soil is dry. The smart machine turns on the water.”\n- T asks: “Do we love the garden? Do we pick the flowers?” T reminds Ss to water the plants and protect green trees.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss look, listen and mime the water.\n- Ss answer: “Yes!” / “No!”"},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter G g, the sound /g/ and the words garden, gate, girl and goat again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":16,"tiet":1,"bai":"Unit 7: In the garden – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “There’s a garden.” to say what there is in a garden.\n- Say the words garden, gate, girl and goat in the sentence pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Love nature and look after plants.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.1CB1a): Look at the poster on the projector and listen to the song audio to find the girl, the goat and the gate.","dodung":"- Teacher: Teacher’s guide pages 66, 62, audio, website hoclieu.vn, poster (Unit 7), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 33, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (garden, gate, girl and goat); Ss say the words.\n- T says: “Open your books at page 33.” and shows Unit 7: In the garden, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “There’s a garden.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  There’s a garden.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “There’s a garden.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “There’s a garden.”\n- Ss say the sentence for each picture:\n  Picture a – There’s a garden.\n  Picture b – There’s a gate.\n  Picture c – There’s a girl.\n  Picture d – There’s a goat.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about a girl and a goat in the garden with actions.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the Unit 7 poster on the projector and plays the song audio; Ss point to the girl, the goat and the gate when they hear the words.\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: point to the girl, the goat and the gate.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point to the poster on the screen.\n- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “There’s a garden.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":17,"tiet":1,"bai":"Unit 8: In the park – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter H h and say its sound /h/ correctly.\n- Listen, point and say the words hair, hand, head and horse correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter H h.\n2. Skills: Listening and speaking\n3. Attributes:\n- Play safely and kindly in the park.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.1CB1a): Listen to the audio on the class computer and point to the right body part or picture (hair, hand, head, horse).","dodung":"- Teacher: Teacher’s guide pages 63, 64, 65, audio Track 41, website hoclieu.vn, flashcards/pictures (Unit 8), poster (Unit 8), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 34, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 7.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Lucky box”: T puts the pictures of Unit 7 (garden, gate, girl and goat) in a box.\n- Ss take turns to pick a picture and say the word; the class claps.\n- T says: “Open your books at page 34.” and shows Unit 8: In the park.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss watch.\n- Ss pick a picture and say the word.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /h/ of the letter H h and the words hair, hand, head and horse.\n* Procedure:\n- T shows the letter card H h and says the sound /h/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ hair: tóc (mime)\n+ hand: bàn tay (mime)\n+ head: cái đầu (mime)\n+ horse: con ngựa (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T plays the word audio on the class computer in a new order; Ss touch their hair, hand or head, or point to the horse.","hs":"- Ss look and listen.\n- Ss say the sound /h/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen and touch or point."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /h/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter H h correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter H h on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter H h, the sound /h/ and the words hair, hand, head and horse again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":18,"tiet":1,"bai":"Semester I Test & Feedback – Self-check","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters and sounds of Units 1–8: B b, C c, A a, D d, I i, E e, G g, H h.\n- Recognise the words of Units 1–8 when they listen and look at pictures.\n- Use the patterns learnt: “Hi, I’m …”, “I have a …”, “This is my …”, “This is a …”, “I like …”, “It’s a red …”, “There’s a …”.\n- Do the Semester I test and listen to the teacher’s feedback.\n2. Skills: Listening and speaking\n3. Attributes:\n- Work on their own, honestly and carefully during the test.\n- Listen to the feedback and try to do better.\n4. Digital Competence (1.1CB1a): Listen to the test recordings on the class computer and find the right pictures on the test paper.","dodung":"- Teacher: audio (test recordings), paper tests, flashcards (Units 1–8), computer, speakers, lesson plan.\n- Pupils: pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (3’)","gv":"* Aims: To help Ss feel relaxed before the test.\n* Procedure:\n- T greets the class and sings the “Hello” song (Unit 1) with Ss.\n- T tells Ss: “Today we do a small test. Listen carefully and do your best!”","hs":"- Ss greet T and sing.\n- Ss listen."},{"ten":"2. Test instructions (4’)","gv":"* Aims: Ss understand how to do each part of the test.\n* Procedure:\n- T gives out the test papers and asks Ss to write or trace their names.\n- T shows an example for each part on the board: listen and tick, listen and number, look and circle the letter.\n- T checks that every S has a pencil.","hs":"- Ss get the papers and trace their names.\n- Ss look at the examples and do the example with T.\n- Ss get ready."},{"ten":"3. Listening test (13’)","gv":"* Aims: To check Ss’ listening skills.\n* Procedure:\n- (Digital competence 1.1CB1a) T plays each part of the test audio on the class computer twice; Ss listen and find the right pictures.\n- Part 1: Listen and tick.\n- Part 2: Listen and number.\n- Part 3: Look and circle the right letter.\n- T walks around and makes sure Ss work on their own.","hs":"- Ss listen to the recordings and look at the pictures.\n- Ss tick.\n- Ss number.\n- Ss circle.\n- Ss work on their own."},{"ten":"4. Speaking test (10’)","gv":"* Aims: To check Ss’ speaking skills.\n* Procedure:\n- T collects the papers; the class colours a picture quietly.\n- T calls Ss one by one or in pairs: T points to pictures (e.g. ball, cake, hat, dog, fish, pen, goat, horse); Ss say the words.\n- T shows a picture and asks Ss to say one sentence, e.g. “I have a car.” / “This is my bag.” / “I like milk.”\n- T notes each S’s result.","hs":"- Ss hand in the papers and colour quietly.\n- Ss say the words.\n- Ss say one sentence.\n- Ss wait for their turn quietly."},{"ten":"5. Feedback and self-check (5’)","gv":"* Aims: To give feedback and encourage Ss.\n* Procedure:\n- T gives general feedback on the test: good points and common mistakes (sounds, words).\n- T says the difficult words again; Ss repeat.\n- Self-check: Ss colour a smiley face for “I can listen” and “I can say the words”.\n- T praises the class and says: “Goodbye, class!”","hs":"- Ss listen to the feedback.\n- Ss repeat the words.\n- Ss colour the smiley faces.\n- Ss say: “Goodbye, teacher!”"}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":19,"tiet":1,"bai":"Unit 9: In the shop – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter O o and say its sound /ɒ/ correctly.\n- Listen, point and say the words clocks, locks, mops and pots correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter O o.\n2. Skills: Listening and speaking\n3. Attributes:\n- Help their parents with the housework.\n- Be friendly, take turns and help friends in pairs and groups.\n4. Digital Competence (1.1CB1a): Look at the flashcard pictures on the projector and listen to the audio to find the right things in the shop (clocks, locks, mops, pots).","dodung":"- Teacher: Teacher’s guide pages 74, 75, 76, audio Track 50, website hoclieu.vn, flashcards/pictures (Unit 9), poster (Unit 9), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 40, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 8.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Jump and say”: T puts the flashcards of Unit 8 (hair, hand, head and horse) on the floor.\n- T says a word; a S jumps onto the right card and says the word.\n- T says: “Open your books at page 40.” and shows Unit 9: In the shop.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss jump and say the words.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /ɒ/ of the letter O o and the words clocks, locks, mops and pots.\n* Procedure:\n- T shows the letter card O o and says the sound /ɒ/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ clocks: những cái đồng hồ (picture)\n+ locks: những cái khoá (picture)\n+ mops: những cây lau nhà (picture)\n+ pots: những cái nồi (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T shows the shop picture on the projector and plays the word audio; Ss come up and point to the clocks, locks, mops and pots.","hs":"- Ss look and listen.\n- Ss say the sound /ɒ/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen, come up and point on the screen."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /ɒ/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter O o correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter O o on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter O o, the sound /ɒ/ and the words clocks, locks, mops and pots again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":20,"tiet":1,"bai":"Unit 9: In the shop – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “How many clocks?” – “Two.” to ask and answer about how many things there are.\n- Count from one to five and say the words clocks, locks, mops and pots in the pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Help their parents with the housework.\n- Listen to the teacher and friends politely.\n4. Digital Competence (1.1CB1a): Count the things in the pictures on the projector and listen to the audio to check their answers.","dodung":"- Teacher: Teacher’s guide pages 79, 80, audio Tracks 53, 54, website hoclieu.vn, flashcards/pictures (Unit 9), poster (Unit 9), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 42, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (clocks, locks, mops and pots); Ss say the words.\n- T says: “Open your books at page 42.” and shows Unit 9: In the shop, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “How many clocks?” – “Two.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  How many clocks?\n  Two.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “How many clocks?” – “Two.” to talk about the pictures.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the pictures on the projector; Ss count the things aloud, then T plays the audio so Ss check their answers.\n- T points to each picture and elicits the word.\n- T models picture a: “How many clocks? – Two.”\n- Ss say the sentence for each picture:\n  Picture a – How many clocks? – Two.\n  Picture b – How many locks? – Three.\n  Picture c – How many pots? – Four.\n  Picture d – How many mops? – Five.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss count aloud, listen and check.\n- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about things in the shop with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: show the numbers with their fingers.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “How many clocks?” – “Two.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":21,"tiet":1,"bai":"Unit 10: At the zoo – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter M m and say its sound /m/ correctly.\n- Listen, point and say the words mango, monkey, mother and mouse correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter M m.\n2. Skills: Listening and speaking\n3. Attributes:\n- Love animals and be kind to them.\n- Listen to the teacher and friends politely.\n4. Digital Competence (1.1CB1b): Search the Internet for videos of monkey sounds under the teacher’s safe guidance.","dodung":"- Teacher: Teacher’s guide pages 81, 82, 83, audio Track 55, website hoclieu.vn, flashcards/pictures (Unit 10), poster (Unit 10), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 43, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 9.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T sticks the flashcards of Unit 9 on the board (clocks, locks, mops and pots).\n- Game “Slap the board”: T says a word; one S from each team runs and slaps the right card.\n- T says: “Open your books at page 43.” and shows Unit 10: At the zoo.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss play in two teams and say the words aloud.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /m/ of the letter M m and the words mango, monkey, mother and mouse.\n* Procedure:\n- T shows the letter card M m and says the sound /m/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ mango: quả xoài (picture)\n+ monkey: con khỉ (picture)\n+ mother: mẹ (picture)\n+ mouse: con chuột (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /m/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /m/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter M m correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter M m on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 1.1CB1b) T opens a safe video website for children on the class computer and types “monkey sounds for kids” while Ss watch; T plays a short safe video (about 30 seconds).\n- Ss listen, copy the monkey sound and say: “Monkey!”\n- T reminds Ss: watch videos on the Internet only with a teacher or with parents.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss watch T search safely.\n- Ss copy the sound and say: “Monkey!”\n- Ss listen and repeat the rule."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter M m, the sound /m/ and the words mango, monkey, mother and mouse again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":22,"tiet":1,"bai":"Unit 10: At the zoo – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “That’s a monkey.” to point to an animal or a thing far away and name it.\n- Say the words monkey, mouse, mango (and horse from Unit 8) in the pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Love animals and be kind to them.\n- Love learning English and be confident when speaking.\n4. Digital Competence (AI 1.A1.1): Understand simply that people decide what to feed animals and AI can only suggest menus based on the data it has.","dodung":"- Teacher: Teacher’s guide pages 85, 86, audio Tracks 58, 59, website hoclieu.vn, flashcards/pictures (Unit 10), poster (Unit 10), computer, projector, a picture of a zookeeper with a tablet showing a food list, lesson plan.\n- Pupils: Pupil’s Book page 45, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (mango, monkey, mother and mouse); Ss say the words.\n- T says: “Open your books at page 45.” and shows Unit 10: At the zoo, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “That’s a monkey.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  That’s a monkey.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (9’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “That’s a monkey.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “That’s a monkey.”\n- Ss say the sentence for each picture:\n  Picture a – That’s a monkey.\n  Picture b – That’s a mouse.\n  Picture c – That’s a mango.\n  Picture d – That’s a horse.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (12’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about animals at the zoo with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: act like a monkey and a mouse.\n- Groups take turns to sing; then the whole class sings together.\n- (AI 1.A1.1) T shows a picture of a zookeeper and a tablet with a food list: bananas, mango, nuts. T says: “The AI says: mango. Who decides? The zookeeper!”\n- Game “Zookeeper”: T holds up a food card as the “AI” idea; Ss (the zookeepers) say “Yes!” or “No!” for the animal, then say: “That’s a monkey. That’s a mango.”","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class.\n- Ss look, listen and say: “The zookeeper!”\n- Ss play and say the sentences."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “That’s a monkey.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":23,"tiet":1,"bai":"Fun time 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters O o and M m and their sounds /ɒ/, /m/.\n- Say the words of Units 9 and 10: clocks, locks, mops, pots, mango, monkey, mother and mouse.\n- Use the patterns “How many …? – …” and “That’s a …” in games.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be friendly, take turns and help friends in pairs and groups.\n- Play fairly and cheer for their friends.\n4. Digital Competence (1.1CB1a): Look at the pictures of Units 9 and 10 on the projector and find the right picture when they hear a word.","dodung":"- Teacher: Teacher’s guide pages 112–114, audio, website hoclieu.vn, flashcards/pictures (Units 9 and 10), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 46, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a happy atmosphere and revise the units.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss sing the unit song from Unit 10 with actions.\n- T says: “Open your books at page 46.” and shows Fun time 3.","hs":"- Ss greet T.\n- Ss sing and do the actions.\n- Ss open their books."},{"ten":"2. Revision (8’)","gv":"Revision of letters and words.\n* Aims: Ss can say the letters O o, M m and the words of Units 9 and 10.\n* Procedure:\n- T shows the letter cards O o and M m; Ss say the letters and the sounds.\n- T shows the flashcards; Ss say the words:\n+ clocks: những cái đồng hồ (picture)\n+ locks: những cái khoá (picture)\n+ mops: những cây lau nhà (picture)\n+ pots: những cái nồi (picture)\n+ mango: quả xoài (picture)\n+ monkey: con khỉ (picture)\n+ mother: mẹ (picture)\n+ mouse: con chuột (picture)\n- Game “What’s missing?” with the flashcards.\n- (Digital competence 1.1CB1a) T shows the pictures of Units 9 and 10 on the projector (hoclieu.vn); T says a word, Ss come up and point to the right picture.","hs":"- Ss say the letters and the sounds.\n- Ss say the words: chorus, groups, individuals.\n- Ss play the game.\n- Ss listen, come up and point to the right picture on the screen."},{"ten":"3. Practice (10’)","gv":"Activity 1. Look, count and say.\n* Aims: Ss can find the things in the picture and say the words.\n* Procedure:\n- T shows the big picture and asks: “How many clocks? How many pots?”\n- Ss count the things together and answer: “Two.” / “Three.”\n- T points to the animals far away and Ss say: “That’s a monkey.” / “That’s a mouse.”","hs":"- Ss look and listen.\n- Ss find, point and say.\n- Ss check the answers."},{"ten":"4. Production (11’)","gv":"Activity 2. Let’s play: “Monkey says”.\n* Aims: Ss can use the words and patterns in a fun activity.\n* Procedure:\n- T is the monkey: “Monkey says: touch the mops!” / “Monkey says: point to the mango!”; Ss point to the right pictures on the board.\n- Ss take turns to be the monkey and give the orders.\n- T praises the best teams.","hs":"- Ss listen and point to the pictures.\n- Some Ss give the orders.\n- Ss clap for the winners."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which words of Units 9 and 10 they like best.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the words to your family.","hs":"- Ss say their favourite words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":24,"tiet":1,"bai":"Unit 11: At the bus stop – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter U u and say its sound /ʌ/ correctly.\n- Listen, point and say the words bus, run, sun and truck correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter U u.\n2. Skills: Listening and speaking\n3. Attributes:\n- Wait at the bus stop safely and follow the road rules.\n- Love learning English and be confident when speaking.\n4. Digital Competence (4.3CB1a): Know the health risk of walking while looking at a phone, and stay safe in the sun.","dodung":"- Teacher: Teacher’s guide pages 91, 92, 93, audio Track 60, website hoclieu.vn, flashcards/pictures (Unit 11), computer, projector, a picture of a child walking in the sun while looking at a phone, lesson plan.\n- Pupils: Pupil’s Book page 48, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 10.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T shows the flashcards of Unit 10 one by one (mango, monkey, mother and mouse); Ss say the words.\n- Game “What’s missing?”: T hides one card; Ss say the missing word.\n- T says: “Open your books at page 48.” and shows Unit 11: At the bus stop.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the words.\n- Ss guess the missing card.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /ʌ/ of the letter U u and the words bus, run, sun and truck.\n* Procedure:\n- T shows the letter card U u and says the sound /ʌ/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ bus: xe buýt (picture)\n+ run: chạy (mime)\n+ sun: mặt trời (picture)\n+ truck: xe tải (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /ʌ/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /ʌ/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter U u correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter U u on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 4.3CB1a) T shows a picture of a child walking to the bus stop in the sun and looking at a phone. T asks: “Is it safe?”\n- T teaches a simple rule with actions: “Stop. Look up. Put the phone away.” and “Wear a hat in the sun.”\n- Ss say the rule and mime it.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss answer: “No!”\n- Ss listen and copy the actions.\n- Ss say and mime the rule."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter U u, the sound /ʌ/ and the words bus, run, sun and truck again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":25,"tiet":1,"bai":"Unit 11: At the bus stop – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “He’s running.” – “She’s running.” to say that a boy or a girl is running.\n- Tell a boy (he) from a girl (she) in the pictures and say the word run.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Wait at the bus stop safely and follow the road rules.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.1CB1a): Look at the pictures on the projector and listen to the audio to find who is running (he or she).","dodung":"- Teacher: Teacher’s guide pages 95, 96, 97, audio, website hoclieu.vn, computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 50, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (bus, run, sun and truck); Ss say the words.\n- T says: “Open your books at page 50.” and shows Unit 11: At the bus stop, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “He’s running.” – “She’s running.”.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the pictures on the projector and plays the audio; Ss point to the boy or the girl who is running.\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  He’s running.\n  She’s running.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss listen and point to the boy or the girl on the screen.\n- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “He’s running.” – “She’s running.” in a short talk.\n* Procedure:\n- T points to the pictures and asks: “Boy or girl?”\n- T models: (a boy) “He’s running.” – (a girl) “She’s running.”\n- Ss look at each picture and say “He’s running.” or “She’s running.”: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs: one S runs on the spot, the partner says “He’s running.” / “She’s running.”\n- T praises Ss and corrects pronunciation.","hs":"- Ss answer: “Boy!” / “Girl!”\n- Ss listen and repeat.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs act and say in front of the class.\n- Ss listen."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about a boy running in the sun with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: run on the spot.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “He’s running.” – “She’s running.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":26,"tiet":1,"bai":"Unit 12: At the lake – Lesson 1 & 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter L l and say its sound /l/ correctly.\n- Listen, point and say the words lake, leaf, lemons and Lucy correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter L l.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep lakes and parks clean.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (3.1CB1a): Practise drawing a simple digital leaf or lemon on the computer.","dodung":"- Teacher: Teacher’s guide pages 98, 99, 100, audio Track 65, website hoclieu.vn, flashcards/pictures (Unit 12), computer, projector, Paint on the class computer, lesson plan.\n- Pupils: Pupil’s Book page 51, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 11.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Pass the ball”: T plays music; Ss pass a ball around the class.\n- When the music stops, the S with the ball says a word from Unit 11 (bus, run, sun and truck).\n- T says: “Open your books at page 51.” and shows Unit 12: At the lake.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss pass the ball.\n- Ss say a word when the music stops.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /l/ of the letter L l and the words lake, leaf, lemons and Lucy.\n* Procedure:\n- T shows the letter card L l and says the sound /l/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ lake: cái hồ (picture)\n+ leaf: chiếc lá (realia)\n+ lemons: những quả chanh (realia)\n+ Lucy: bạn Lucy (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /l/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /l/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter L l correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter L l on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 3.1CB1a) T opens Paint and shows the brush, the oval shape and the colours green and yellow.\n- 3–4 Ss take turns to draw a simple leaf or lemon with T’s help and say: “leaf” / “lemons”.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss look at the tools on the screen.\n- 3–4 Ss draw in Paint and say the word; the class claps."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter L l, the sound /l/ and the words lake, leaf, lemons and Lucy again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":27,"tiet":1,"bai":"Unit 12: At the lake – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “Look at Lucy.” – “Look at the lemons.” to ask a friend to look at someone or something.\n- Use “Look at her. / Look at him. / Look at the …” with the words lake, leaf, lemons.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Keep lakes and parks clean.\n- Be friendly, take turns and help friends in pairs and groups.\n4. Digital Competence (1.1CB1a): Look at the pictures on the projector and listen to the song audio to find Lucy, the lake, the leaf and the lemons.","dodung":"- Teacher: Teacher’s guide pages 102, 103, audio Tracks 68, 69, website hoclieu.vn, computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 53, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (lake, leaf, lemons and Lucy); Ss say the words.\n- T says: “Open your books at page 53.” and shows Unit 12: At the lake, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “Look at Lucy.” – “Look at the lemons.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  Look at Lucy.\n  Look at the lemons.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “Look at Lucy.” – “Look at the lemons.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “Look at her.”\n- Ss say the sentence for each picture:\n  Picture a – Look at her.\n  Picture b – Look at him.\n  Picture c – Look at the lemons.\n  Picture d – Look at the lake.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about Lucy running around the lake and a falling leaf with actions.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the song picture on the projector and plays the song audio; Ss point to Lucy, the lake, the leaf and the lemons when they hear the words.\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: point and make a “falling leaf” action with their hands.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point on the screen.\n- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “Look at Lucy.” – “Look at the lemons.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":28,"tiet":1,"bai":"Unit 13: In the school canteen – Lesson 1, 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter N n and say its sound /n/ correctly.\n- Listen, point and say the words bananas, noodles, nuts and Nick correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter N n.\n2. Skills: Listening and speaking\n3. Attributes:\n- Eat healthy snacks and keep the canteen clean.\n- Be friendly, take turns and help friends in pairs and groups.\n4. Digital Competence (1.1CB1a): Listen to the audio on the class computer and point to the right food pictures (bananas, noodles, nuts).","dodung":"- Teacher: Teacher’s guide pages 109, 110, 111, audio Track 74, website hoclieu.vn, flashcards/pictures (Unit 13), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 57, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 12.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Lucky box”: T puts the pictures of Unit 12 (lake, leaf, lemons and Lucy) in a box.\n- Ss take turns to pick a picture and say the word; the class claps.\n- T says: “Open your books at page 57.” and shows Unit 13: In the school canteen.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss watch.\n- Ss pick a picture and say the word.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /n/ of the letter N n and the words bananas, noodles, nuts and Nick.\n* Procedure:\n- T shows the letter card N n and says the sound /n/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ bananas: những quả chuối (realia)\n+ noodles: mì sợi (picture)\n+ nuts: các loại hạt (realia)\n+ Nick: bạn Nick (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T plays the word audio on the class computer in a new order; Ss point to the right food picture in their books.","hs":"- Ss look and listen.\n- Ss say the sound /n/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen and point to the right picture."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /n/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter N n correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter N n on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter N n, the sound /n/ and the words bananas, noodles, nuts and Nick again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":29,"tiet":1,"bai":"Unit 13: In the school canteen – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “He’s having nuts.” – “She’s having noodles.” to say what a boy or a girl is having (eating).\n- Say the words bananas, noodles, nuts (and chips from Unit 5) in the pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Eat healthy snacks and keep the canteen clean.\n- Listen to the teacher and friends politely.\n4. Digital Competence (1.1CB1a): Look at the canteen pictures on the projector and listen to the audio to find what he or she is having.","dodung":"- Teacher: Teacher’s guide pages 113, 114, 115, audio Tracks 77, 78, website hoclieu.vn, flashcards/pictures (Unit 13), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 59, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (bananas, noodles, nuts and Nick); Ss say the words.\n- T says: “Open your books at page 59.” and shows Unit 13: In the school canteen, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “He’s having nuts.” – “She’s having noodles.”.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the canteen pictures on the projector and plays the audio; Ss point to the boy with the nuts and the girl with the noodles.\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  He’s having nuts.\n  She’s having noodles.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss listen and point on the screen.\n- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “He’s having nuts.” – “She’s having noodles.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “He’s having nuts.”\n- Ss say the sentence for each picture:\n  Picture a – He’s having nuts.\n  Picture b – He’s having chips.\n  Picture c – She’s having noodles.\n  Picture d – She’s having bananas.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song about lunch in the school canteen with actions.\n* Procedure:\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: mime eating noodles and bananas.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “He’s having nuts.” – “She’s having noodles.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":30,"tiet":1,"bai":"Unit 14: In the toy shop – Lesson 1, 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter T t and say its sound /t/ correctly.\n- Listen, point and say the words teddy bear, tiger, top and turtle correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter T t.\n2. Skills: Listening and speaking\n3. Attributes:\n- Share toys with friends and keep them tidy.\n- Listen to the teacher and friends politely.\n4. Digital Competence (4.2CB1b): Keep information safe: do not share photos of expensive gifts online, so that bad people cannot take advantage of them.","dodung":"- Teacher: Teacher’s guide pages 116, 117, 118, audio Track 79, website hoclieu.vn, flashcards/pictures (Unit 14), poster (Unit 14), computer, projector, a picture of a new teddy bear and a phone, lesson plan.\n- Pupils: Pupil’s Book page 60, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 13.\n* Procedure:\n- T greets the class: “Hello, class!”\n- Game “Jump and say”: T puts the flashcards of Unit 13 (bananas, noodles, nuts and Nick) on the floor.\n- T says a word; a S jumps onto the right card and says the word.\n- T says: “Open your books at page 60.” and shows Unit 14: In the toy shop.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss jump and say the words.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /t/ of the letter T t and the words teddy bear, tiger, top and turtle.\n* Procedure:\n- T shows the letter card T t and says the sound /t/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ teddy bear: gấu bông (realia)\n+ tiger: con hổ (picture)\n+ top: con quay (realia)\n+ turtle: con rùa (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /t/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /t/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter T t correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter T t on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 4.2CB1b) T shows a picture of a new teddy bear and a phone taking a photo. T asks: “Can we put this photo on the Internet for everyone to see?”\n- T explains simply: “Keep photos of your gifts at home. Show them to your family, not to strangers online.”\n- Game “Thumbs up, thumbs down”: T says simple situations; Ss show thumbs up (safe) or thumbs down (not safe).","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss answer: “No!”\n- Ss listen and repeat: “Keep it at home.”\n- Ss play the game."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter T t, the sound /t/ and the words teddy bear, tiger, top and turtle again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":31,"tiet":1,"bai":"Fun time 4","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters N n and T t and their sounds /n/, /t/.\n- Say the words of Units 13 and 14: bananas, noodles, nuts, Nick, teddy bear, tiger, top and turtle.\n- Use the patterns “He’s having … / She’s having …” in games.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be friendly, take turns and help friends in pairs and groups.\n- Play fairly and cheer for their friends.\n4. Digital Competence (3.3CB1a): Respect copyright: write their name on their drawing before submitting it to the teacher on the interactive board.","dodung":"- Teacher: flashcards/pictures (Units 13 and 14), audio, interactive board, computer, drawing paper, lesson plan.\n- Pupils: Pupil’s Book, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a happy atmosphere and revise the units.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss sing the unit song from Unit 13 with actions.\n- T says: “Open your books, please.” and shows Fun time 4.","hs":"- Ss greet T.\n- Ss sing and do the actions.\n- Ss open their books."},{"ten":"2. Revision (7’)","gv":"Revision of letters and words.\n* Aims: Ss can say the letters N n, T t and the words of Units 13 and 14.\n* Procedure:\n- T shows the letter cards N n and T t; Ss say the letters and the sounds.\n- T shows the flashcards; Ss say the words:\n+ bananas: những quả chuối (realia)\n+ noodles: mì sợi (picture)\n+ nuts: các loại hạt (realia)\n+ Nick: bạn Nick (picture)\n+ teddy bear: gấu bông (realia)\n+ tiger: con hổ (picture)\n+ top: con quay (realia)\n+ turtle: con rùa (picture)\n- Game “What’s missing?” with the flashcards.","hs":"- Ss say the letters and the sounds.\n- Ss say the words: chorus, groups, individuals.\n- Ss play the game."},{"ten":"3. Practice (9’)","gv":"Activity 1. Look and say.\n* Aims: Ss can find the things in the picture and say the words.\n* Procedure:\n- T shows pictures of the canteen and the toy shop.\n- T points to a picture; Ss say the word (bananas, noodles, nuts, teddy bear, tiger, top, turtle).\n- T points to a boy or a girl eating; Ss say: “He’s having nuts.” / “She’s having noodles.”","hs":"- Ss look and listen.\n- Ss find, point and say.\n- Ss check the answers."},{"ten":"4. Production (13’)","gv":"Activity 2. Let’s draw and show.\n* Aims: Ss can use the words and patterns in a fun activity.\n* Procedure:\n- (Digital competence 3.3CB1a) Ss draw one thing from Units 13 and 14 (a teddy bear, a top, noodles, bananas …) on paper or on the interactive board.\n- T shows how to write your name on the drawing: “This is my picture. I write my name.”\n- Ss write their names, then T shows the drawings on the interactive board; each S points to his or her picture and says the word.","hs":"- Ss draw one thing.\n- Ss watch T.\n- Ss write their names, show their drawings and say the words."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss which words of Units 13 and 14 they like best.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the words to your family.","hs":"- Ss say their favourite words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":32,"tiet":1,"bai":"Unit 15: At the football match – Lesson 1, 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter F f and say its sound /f/ correctly.\n- Listen, point and say the words face, father, foot and football correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter F f.\n2. Skills: Listening and speaking\n3. Attributes:\n- Play sport fairly and cheer for their friends.\n- Love learning English and be confident when speaking.\n4. Digital Competence (1.1CB1a): Listen to the audio on the class computer and point to the right pictures (face, father, foot, football).","dodung":"- Teacher: Teacher’s guide pages 125, 126, 127, audio Track 84, website hoclieu.vn, flashcards/pictures (Unit 15), poster (Unit 15), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 65, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 14.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T sticks the flashcards of Unit 14 on the board (teddy bear, tiger, top and turtle).\n- Game “Slap the board”: T says a word; one S from each team runs and slaps the right card.\n- T says: “Open your books at page 65.” and shows Unit 15: At the football match.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss look and say the words.\n- Ss play in two teams and say the words aloud.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (12’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /f/ of the letter F f and the words face, father, foot and football.\n* Procedure:\n- T shows the letter card F f and says the sound /f/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ face: khuôn mặt (mime)\n+ father: bố (picture)\n+ foot: bàn chân (mime)\n+ football: quả bóng đá (realia)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.\n- (Digital competence 1.1CB1a) T plays the word audio on the class computer in a new order; Ss point to their face or foot, or to the father or the football in their books.","hs":"- Ss look and listen.\n- Ss say the sound /f/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class.\n- Ss listen and point."},{"ten":"3. Practice (12’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /f/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (5’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter F f correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter F f on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter F f, the sound /f/ and the words face, father, foot and football again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":33,"tiet":1,"bai":"Unit 15: At the football match – Lesson 3","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Use the sentence pattern “Point to your hand.” to follow and give the instruction “Point to your …”.\n- Say the body words face, foot, hand and hair in the pattern.\n- Sing the unit song with actions.\n2. Skills: Listening and speaking\n3. Attributes:\n- Play sport fairly and cheer for their friends.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.1CB1a): Watch the song pictures on the projector, listen and point to the right body parts.","dodung":"- Teacher: Teacher’s guide pages 129–131, audio Tracks 87, 88, website hoclieu.vn, flashcards/pictures (Unit 15), poster (Unit 15), computer, projector, lesson plan.\n- Pupils: Pupil’s Book page 67, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To revise the letter, the sound and the words of the unit.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss say the chant from Lesson 2 with claps.\n- Game “Flash the card”: T flashes the flashcards quickly (face, father, foot and football); Ss say the words.\n- T says: “Open your books at page 67.” and shows Unit 15: At the football match, Lesson 3.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the chant and clap.\n- Ss say the words quickly.\n- Ss open their books."},{"ten":"2. Presentation (8’)","gv":"Activity 6. Listen and repeat.\n* Aims: Ss can understand and repeat the sentence pattern “Point to your hand.”.\n* Procedure:\n- T shows the picture and asks Ss what they can see.\n- T plays the recording twice; Ss listen and point to the picture.\n- T plays it again, pausing after each sentence; Ss repeat.\n- Model sentence(s): T says the pattern with gestures and writes it on the board:\n  Point to your hand.\n- Ss repeat: chorus, groups, individuals.","hs":"- Ss look and answer (words or short answers).\n- Ss listen and point.\n- Ss listen and repeat.\n- Ss watch and listen.\n- Ss repeat: chorus, groups, individuals."},{"ten":"3. Practice (10’)","gv":"Activity 7. Let’s talk.\n* Aims: Ss can use “Point to your hand.” to talk about the pictures.\n* Procedure:\n- T points to each picture and elicits the word.\n- T models picture a: “Point to your hand.”\n- Ss say the sentence for each picture:\n  Picture a – Point to your hand.\n  Picture b – Point to your face.\n  Picture c – Point to your hair.\n  Picture d – Point to your foot.\n- Practice: T – Ss, half class – half class, then pairs.\n- T invites 3–4 pairs to talk in front of the class and praises them.","hs":"- Ss say the words.\n- Ss listen and repeat.\n- Ss look at the pictures and say the sentences.\n- Ss practise in chorus, in groups, then in pairs.\n- Pairs talk in front of the class."},{"ten":"4. Production (11’)","gv":"Activity 8. Let’s sing.\n* Aims: Ss can sing the unit song “Point to your face, point to your foot …” with actions.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows the song picture on the projector and plays the song audio; Ss listen and point to their face, foot, hair and head.\n- T plays the song once; Ss listen and point to the pictures.\n- T teaches the song line by line; Ss repeat.\n- Ss sing with actions: point to their face, foot, hair and head.\n- Groups take turns to sing; then the whole class sings together.","hs":"- Ss watch, listen and point.\n- Ss listen and point.\n- Ss repeat line by line.\n- Ss sing and do the actions.\n- Ss sing in groups and as a class."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks some Ss to say the pattern “Point to your hand.” with a picture.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Sing the song for your family.","hs":"- Some Ss say the sentences.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":34,"tiet":1,"bai":"Unit 16: At home – Lesson 1, 2","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Recognise the letter W w and say its sound /w/ correctly.\n- Listen, point and say the words wash, water, window and Wendy correctly.\n- Say the chant, listen and tick the right pictures, and trace the letter W w.\n2. Skills: Listening and speaking\n3. Attributes:\n- Wash their hands and save water at home.\n- Take part in games and activities with classmates actively.\n4. Digital Competence (1.3CB1b): Sort pictures of houses into the “My Home” folder on the class computer.","dodung":"- Teacher: Teacher’s guide pages 132, 133, 134, audio Track 89, website hoclieu.vn, flashcards/pictures (Unit 16), poster (Unit 16), computer, projector, a folder “My Home” and 6 pictures on the class computer, lesson plan.\n- Pupils: Pupil’s Book page 68, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a friendly atmosphere and revise the words of Unit 15.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T shows the flashcards of Unit 15 one by one (face, father, foot and football); Ss say the words.\n- Game “What’s missing?”: T hides one card; Ss say the missing word.\n- T says: “Open your books at page 68.” and shows Unit 16: At home.","hs":"- Ss greet T: “Hello, teacher!”\n- Ss say the words.\n- Ss guess the missing card.\n- Ss open their books and look at the picture."},{"ten":"2. Presentation (11’)","gv":"Activity 1. Listen and repeat.\n* Aims: Ss can say the sound /w/ of the letter W w and the words wash, water, window and Wendy.\n* Procedure:\n- T shows the letter card W w and says the sound /w/ three times.\n- T elicits the new words with the flashcards/pictures:\n+ wash: rửa (mime)\n+ water: nước (realia)\n+ window: cửa sổ (picture)\n+ Wendy: bạn Wendy (picture)\n- T plays the recording twice; Ss listen and point to the pictures, then repeat.\n- T models each word three times; Ss repeat.\n- Checking: “Rub out and remember” with the flashcards.\nActivity 2. Point and say.\n* Aims: Ss can point to the pictures and say the words correctly.\n* Procedure:\n- T points to each picture and says the word.\n- T points to a picture at random; Ss say the word.\n- Ss work in pairs: one S points, the other says. T corrects pronunciation.","hs":"- Ss look and listen.\n- Ss say the sound /w/ after T.\n- Ss look at the pictures, listen and guess the words.\n- Ss listen, point and repeat.\n+ Choral repetition (3 times).\n+ Individual repetition (3–4 Ss).\n- Ss play the game.\n- Ss listen and point.\n- Ss say the words.\n- Ss work in pairs, then 3–4 pairs say in front of the class."},{"ten":"3. Practice (10’)","gv":"Activity 3. Listen and chant.\n* Aims: Ss can say the chant with the sound /w/ and the words.\n* Procedure:\n- T plays the chant once; Ss listen.\n- T says the chant line by line and claps the rhythm; Ss repeat.\n- Ss say the chant with T, then in groups, with claps.\nActivity 4. Listen and tick.\n* Aims: Ss can listen and tick the right pictures.\n* Procedure:\n- T points to the pictures and asks Ss to say the words.\n- T plays the recording twice; Ss tick the pictures they hear.\n- T plays it again and checks the answers with the class.","hs":"- Ss listen.\n- Ss listen, clap and repeat line by line.\n- Ss say the chant in chorus and in groups.\n- Ss say the words.\n- Ss listen and tick.\n- Ss check the answers."},{"ten":"4. Production (8’)","gv":"Activity 5. Look and trace.\n* Aims: Ss can trace the letter W w correctly.\n* Procedure:\n- T shows how to write the big letter and the small letter W w on the board.\n- Ss trace the letter in the air with their fingers, then trace in their books with a pencil.\n- T walks around and helps Ss hold the pencil correctly.\n- (Digital competence 1.3CB1b) T shows a folder named “My Home” on the class computer and 6 pictures on the screen (houses, a window, water, a bike …).\n- T models: drag a house picture into the folder “My Home”.\n- 3–4 Ss take turns to drag the house pictures into the folder with T’s help; the class says “Yes!” or “No!”","hs":"- Ss watch T.\n- Ss trace in the air, then in their books.\n- Ss trace carefully.\n- Ss look at the pictures and say the words they know.\n- Ss watch T.\n- 3–4 Ss sort the pictures; the class checks."},{"ten":"5. Wrap-up (2’)","gv":"* Aims: To consolidate the lesson.\n* Procedure:\n- T asks Ss to say the letter W w, the sound /w/ and the words wash, water, window and Wendy again.\n- T praises Ss and says: “Goodbye, class!”\n- Home: Say the chant to your family.","hs":"- Ss say the letter, the sound and the words.\n- Ss say: “Goodbye, teacher!”\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"},
{"lop":1,"mon":"Tiếng Anh","tuan":35,"tiet":1,"bai":"Review 4: Self-check","yccd":"By the end of this lesson, pupils will be able to:\n1. Knowledge:\n- Revise the letters N n, T t, F f, W w and their sounds /n/, /t/, /f/, /w/.\n- Say the words of Units 13–16: bananas, noodles, nuts and Nick; teddy bear, tiger, top and turtle; face, father, foot and football; wash, water, window and Wendy.\n- Use the patterns “He’s having … / She’s having …” and “Point to your …”.\n- Self-check what they can do at the end of the school year.\n2. Skills: Listening and speaking\n3. Attributes:\n- Be honest when they check themselves.\n- Love learning English and be proud of their progress.\n4. Digital Competence (1.1CB1a): Look at the pictures of Units 13–16 on the projector and listen to the audio to find the right answers.","dodung":"- Teacher: audio, flashcards/pictures (Units 13–16), letter cards, self-check cards, computer, projector, lesson plan.\n- Pupils: Pupil’s Book, pencils, crayons.","hoatdong":[{"ten":"1. Warm-up (4’)","gv":"* Aims: To create a happy atmosphere.\n* Procedure:\n- T greets the class: “Hello, class!”\n- T and Ss sing the song “Point to your face …” (Unit 15) with actions.","hs":"- Ss greet T.\n- Ss sing and point to their face, foot, hair and head."},{"ten":"2. Revision (8’)","gv":"* Aims: Ss can say the letters, the sounds and the words of Units 13–16.\n* Procedure:\n- T shows the letter cards N n, T t, F f, W w; Ss say the letters and the sounds.\n- T shows the flashcards; Ss say the words:\n+ bananas: những quả chuối (realia)\n+ noodles: mì sợi (picture)\n+ nuts: các loại hạt (realia)\n+ Nick: bạn Nick (picture)\n+ teddy bear: gấu bông (realia)\n+ tiger: con hổ (picture)\n+ top: con quay (realia)\n+ turtle: con rùa (picture)\n+ face: khuôn mặt (mime)\n+ father: bố (picture)\n+ foot: bàn chân (mime)\n+ football: quả bóng đá (realia)\n+ wash: rửa (mime)\n+ water: nước (realia)\n+ window: cửa sổ (picture)\n+ Wendy: bạn Wendy (picture)\n- Game “Slap the board” in two teams.","hs":"- Ss say the letters and the sounds.\n- Ss say the words: chorus, groups, individuals.\n- Ss play the game."},{"ten":"3. Practice (10’)","gv":"* Aims: Ss can listen and find the right pictures.\n* Procedure:\n- (Digital competence 1.1CB1a) T shows pictures of Units 13–16 on the projector and plays the audio (or says the words and sentences).\n- Ss listen and point to the right picture, then say it.\n- T says: “Point to your foot. Point to your face.”; Ss do the actions.\n- T shows a picture and Ss say: “He’s having nuts.” / “She’s having noodles.”","hs":"- Ss look at the screen and listen.\n- Ss point and say.\n- Ss do the actions.\n- Ss say the sentences."},{"ten":"4. Self-check (10’)","gv":"* Aims: Ss can check what they can do.\n* Procedure:\n- T shows a self-check card with pictures and says each line: “I can say the letters N, T, F, W.” / “I can say the words.” / “I can sing the songs.” / “I can talk with my friends.”\n- Ss colour a smiley face for each line they can do.\n- Ss work in pairs: one S points to a picture, the other says the word or a sentence.\n- T helps Ss who need more practice.","hs":"- Ss look and listen.\n- Ss colour the smiley faces.\n- Ss work in pairs.\n- Ss practise with T."},{"ten":"5. Wrap-up (3’)","gv":"* Aims: To finish the school year happily.\n* Procedure:\n- T praises the class for a great year of English.\n- T and Ss sing a goodbye song and say: “Goodbye! See you next year!”\n- Home: Sing the English songs with your family in the summer.","hs":"- Ss listen and clap.\n- Ss sing and say goodbye.\n- Ss remember the task."}],"status":"may-soan","source":"Máy soạn 12/9/2026 theo KHGD tổ Năng khiếu QC1 — chờ tổ Tiếng Anh soát"}
];
